public class SearchComparison { public final SearchResult linear,binary; public SearchComparison(SearchResult l,SearchResult b){linear=l;binary=b;} public void display(){System.out.println("\n=============================================");System.out.println("         SEARCH PERFORMANCE COMPARISON");System.out.println("=============================================");System.out.printf("%-20s %-12s %-15s%n","Algorithm","Steps","Time (ns)");System.out.println("---------------------------------------------");System.out.printf("%-20s %-12d %-15d%n","Linear Search",linear.steps,linear.timeNanos);System.out.printf("%-20s %-12d %-15d%n","Binary Search",binary.steps,binary.timeNanos);System.out.println("---------------------------------------------");System.out.println("Binary Search requires sorted data.");} }
